const crypto = require('crypto');
const secret = $env.WEBHOOK_HMAC_SECRET || '';
const raw = JSON.stringify($input.first().json);
const sig = ($input.first().json._sig || $headers['x-hris-signature'] || '').replace(/^sha256=/, '');
const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
if (!sig || sig.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) {
  throw new Error('401 invalid HMAC signature');
}
return $input.all();

const h = $input.first().json;
for (const f of ['name', 'start_date']) {
  if (!h[f] || String(h[f]).trim() === '') throw new Error(`hire validation: missing ${f}`);
}
if (!/^\d{4}-\d{2}-\d{2}$/.test(h.start_date)) throw new Error('hire validation: bad start_date');
return [{ json: h }];

const h = $input.first().json;
const hireId = h.hire_id || h.email || h.name;
return [{ json: { hire: h, idemKey: `${hireId}:${h.start_date}` } }];
